import{_ as o,o as r,c as n,ag as s}from"./chunks/framework.KxDd3USm.js";const D=JSON.parse('{"title":"10.5 精华题与补充题","description":"","frontmatter":{},"headers":[],"relativePath":"10-标准化与知识产权/91-精华题与补充题.md","filePath":"10-标准化与知识产权/91-精华题与补充题.md"}'),g={name:"10-标准化与知识产权/91-精华题与补充题.md"};function p(a,t,e,B,_,A){return r(),n("div",null,[...t[0]||(t[0]=[s('<h1 id="_10-5-精华题与补充题" tabindex="-1">10.5 精华题与补充题 <a class="header-anchor" href="#_10-5-精华题与补充题" aria-label="Permalink to &quot;10.5 精华题与补充题&quot;">​</a></h1><p><strong>1.</strong> 构成我国保护计算机软件著作权的两个基本法律文件是（ ）。 A. 《著作权法》和《计算机软件保护条例》 B. 《著作权法》和《专利法》 C. 《商标法》和《计算机软件保护条例》 D. 《著作权法》和《标准化法》</p><p><strong>2.</strong> 国际上保护计算机软件知识产权所采用的主要方式是实施（ ）。 A. 合同法 B. 物权法 C. 版权法 D. 刑法</p><p><strong>3.</strong> 某企业的核心技术配方从未申请专利、也未发表，企业通过内部保密制度与竞业协议长期保密。关于该技术配方，下列说法正确的是（ ）。 A. 属于商业秘密，保护期为 20 年 B. 属于商业秘密，只要保密措施有效就持续受保护，他人独立研发出同样配方不侵权 C. 属于商业秘密，保护期为 10 年 D. 因未公开，不受任何法律保护</p><p><strong>4.</strong> 关于软件著作权登记，下列说法正确的是（ ）。 A. 登记是取得软件著作权的法定前提 B. 软件著作权自开发完成之日起产生，登记只是初步证明手段 C. 未经登记的软件不受法律保护 D. 登记后软件著作权才自动产生</p><p><strong>5.</strong> 我国著作权法中，发表权的保护期为（ ）。 A. 永久保护 B. 作者终生及其死亡后 50 年 C. 作品完成后 30 年 D. 作者终生及其死亡后 20 年</p><p><strong>6.</strong> 标准实施后需要进行复审，我国标准的复审周期一般不超过（ ）。 A. 3 年 B. 5 年 C. 8 年 D. 10 年</p><p><strong>7.</strong> 某公司开发的系统需要与另一厂商的老系统对接，但对方拒绝提供软件接口文档，且通过正当途径无法获得该接口的必要信息。该公司为实现兼容而对对方软件进行反编译。该行为（ ）。 A. 构成侵权，反编译一律侵权 B. 不构成侵权，属于软件保护条例规定的为兼容性需要的例外情形 C. 构成侵权，除非事先取得专利许可 D. 不构成侵权，因为软件本无著作权</p><p><strong>8.</strong> 下列标准代号中，属于<strong>强制性</strong>国家标准的是（ ）。 A. GB/T 22239 B. GB 18030 C. GB/Z 20986 D. SJ/T 11234</p><hr><h2 id="补充题-四大权利对比-标准代号-6-道" tabindex="-1">补充题（四大权利对比 + 标准代号 6 道） <a class="header-anchor" href="#补充题-四大权利对比-标准代号-6-道" aria-label="Permalink to &quot;补充题（四大权利对比 + 标准代号 6 道）&quot;">​</a></h2><p><strong>1.</strong> 关于四种知识产权的取得方式，下列说法正确的是（ ）。 A. 著作权、商标权均须登记或注册后才能取得 B. 专利权、商标权须经申请/注册取得，著作权自动产生，商业秘密靠保密措施维持 C. 商业秘密须向主管部门申请登记后方可取得 D. 四种知识产权都实行&quot;先申请原则&quot;</p><p><strong>2.</strong> 某企业开发出一种新型电路板，产品一旦上市即可被对手拆解分析（可被逆向）。该企业希望获得最强独占（即使别人独立研究出同样的方案也不得实施）。下列做法<strong>最合理</strong>的是（ ）。 A. 当作商业秘密长期保密，因为保密期无上限 B. 申请发明专利，用&quot;公开换独占&quot;防止他人独立实施 C. 只申请商标注册 D. 不采取任何保护措施</p><p><strong>3.</strong> 关于标准代号 <code>T/ABC 001</code>，下列说法正确的是（ ）。 A. 它是推荐性国家标准，ABC 为行业代码 B. 它是团体标准，T 在首、后接团体代号 C. 它是企业标准，T 表示推荐 D. 它是强制性标准，必须执行</p><p><strong>4.</strong> 看到标准号自 <code>GB/T 19001</code>，其所属层级与性质是（ ）。 A. 强制性国家标准 B. 推荐性国家标准 C. 团体标准 D. 行业标准</p><p><strong>5.</strong> 四种知识产权中，<strong>允许他人独立研究或通过反向工程获得同样成果而不侵权</strong>的是（ ）。 A. 著作权 B. 专利权 C. 商标权 D. 商业秘密</p><p><strong>6.</strong> 关于商标权保护期的续展与起算，下列说法正确的是（ ）。 A. 自申请日起算，期满自动续展 B. 自核准注册之日起算 10 年，期满前可续展，每次 10 年、次数不限 C. 自首次使用之日起算 D. 自登记之日起算，且只能续展 3 次</p><hr><h2 id="补充题-专利权-商标权-商业秘密专题-10-道" tabindex="-1">补充题（专利权 / 商标权 / 商业秘密专题 10 道） <a class="header-anchor" href="#补充题-专利权-商标权-商业秘密专题-10-道" aria-label="Permalink to &quot;补充题（专利权 / 商标权 / 商业秘密专题 10 道）&quot;">​</a></h2><blockquote><p>2026-10-14 本章背完后加练的一套。与前面各套题<strong>换角度提问</strong>：不考&quot;外观设计几年&quot;这类正面数字，改考保护期的起算点对比、反向问&quot;不能授予专利的&quot;、同日申请与先申请的边界、宽展期的位置。</p></blockquote><p><strong>1.</strong> 某公司同日提交三项专利申请：①一种新型数据压缩<strong>方法</strong>；②对现有键盘支架结构的小改进；③手机外壳富有美感的新造型。它们的保护期自申请日起算分别为（ ）。 A. 20 年、10 年、15 年 B. 20 年、20 年、10 年 C. 10 年、10 年、15 年 D. 20 年、10 年、10 年</p><p><strong>2.</strong> 专利权与商标权的保护期起算点分别是（ ）。 A. 自授权公告之日；自核准注册之日 B. 自申请之日；自核准注册之日 C. 自申请之日；自申请之日 D. 自授权之日；自首次使用之日</p><p><strong>3.</strong> 工程师小林所在课题组承担了单位下达的科研任务，小林利用业余时间、在自己家中使用单位登记在册的精密仪器完成了其中一项发明。该发明的专利申请权归（ ）。 A. 小林，因为是在业余时间和个人住所完成的 B. 单位，因为属于执行本单位的任务，且主要利用了本单位的物质技术条件 C. 小林与单位共有 D. 小林，但单位有权免费实施该发明</p><p><strong>4.</strong> 甲、乙两公司于<strong>同一日</strong>分别就同样的发明创造提出专利申请，两件申请均符合授权条件。此时专利权的处理方式是（ ）。 A. 由双方协商确定申请人 B. 由国务院专利行政部门抽签决定由谁获得 C. 由双方共同享有该专利权 D. 由提交材料更完整的一方获得</p><p><strong>5.</strong> 下列各项中，依照我国专利法<strong>不能</strong>被授予专利权的是（ ）。 A. 一种新型白酒的酿造工艺 B. 一种通过激光手术矫正近视的方法 C. 一种培育抗病小麦新品种的生产方法 D. 一种逆流式换热器的结构改进</p><p><strong>6.</strong> 关于商业秘密的构成与保护，下列说法正确的是（ ）。 A. 须同时具备不为公众所知悉、具有商业价值、权利人采取相应保密措施三个条件 B. 须经主管部门登记后方受法律保护 C. 保护期为秘密形成之日起 10 年 D. 他人通过反向工程获得同样信息的，构成侵犯商业秘密</p><p><strong>7.</strong> 某乳品企业的菌种配方只在母公司实验室内部流转，产品上市后对手无法从成品中解析出菌种组合；企业希望尽可能长期保持这一技术优势。最合适的保护方式是（ ）。 A. 申请发明专利，保护期 20 年 B. 作为商业秘密保护，依靠保密措施维持 C. 申请实用新型专利，保护期 10 年 D. 申请外观设计专利，保护期 15 年</p><p><strong>8.</strong> 甲、乙两公司就同一种商品上使用的近似商标先后提出注册申请，甲提交在先且两申请均符合注册条件。商标专用权应（ ）。 A. 由先使用者取得，因为商标权自使用之日产生 B. 授予甲公司，商标注册实行先申请原则 C. 由甲、乙两公司共同享有 D. 由两公司抽签决定</p><p><strong>9.</strong> 我国发明专利申请获得授权应当具备的实质性条件是（ ）。 A. 新颖性、创造性、实用性 B. 新颖性、独创性、可复制性 C. 创造性、公开性、实用性 D. 新颖性、独立性、时间性</p><p><strong>10.</strong> 某企业注册商标的有效期届满，其未能在期满前办理续展。按规定，该企业还可以在（ ）的宽展期内办理续展；每次续展注册的有效期为（ ）。 A. 期满后 6 个月；10 年 B. 期满后 6 个月；20 年 C. 期满后 12 个月；10 年 D. 期满前 6 个月；10 年</p><hr>',31)])])}const c=o(g,[["render",p]]);export{D as __pageData,c as default};
